import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.D7xI0JV8.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"zkde.fi","text":"Proof-Gated Execution on Starknet","tagline":"Capital only moves when cryptographic conditions are met. Every action produces a verifiable on-chain receipt.","actions":[{"theme":"brand","text":"The Primitive","link":"/intro"},{"theme":"alt","text":"Live Proof Readout","link":"/proof-readout"},{"theme":"alt","text":"Open App","link":"https://zkde.fi","target":"_blank"}]}},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),i={name:"index.md"};function n(s,e,l,d,c,p){return a(),r("div",null,[...e[0]||(e[0]=[o(`<h2 id="what-this-is" tabindex="-1">What This Is <a class="header-anchor" href="#what-this-is" aria-label="Permalink to &quot;What This Is&quot;">​</a></h2><p>zkde.fi is a reference implementation of <strong>proof-gated private finance</strong> — built on top of the <a href="https://obsqra.xyz" target="_blank" rel="noreferrer">Obsqra Labs</a> proving infrastructure using a SNARK-in-STARK dual-lane architecture.</p><p><strong>Garaga</strong> (Groth16) handles zkML verification in Cairo. <strong>Stone</strong> (STARK) handles execution integrity — the same prover infrastructure that secures Starknet blocks.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AI signal / strategy intent</span></span>
<span class="line"><span>  ↓ zkML inference → Groth16 commitment (EZKL)</span></span>
<span class="line"><span>  ↓ Garaga KZG pairing check in Cairo</span></span>
<span class="line"><span>  ↓ Stone STARK execution envelope</span></span>
<span class="line"><span>  ↓ Policy gate — no proof, no execution</span></span>
<span class="line"><span>  ↓ On-chain receipt → Madara L3 fact registry</span></span></code></pre></div><h2 id="what-s-deployed" tabindex="-1">What&#39;s Deployed <a class="header-anchor" href="#what-s-deployed" aria-label="Permalink to &quot;What&#39;s Deployed&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fact</th><th>Count</th></tr></thead><tbody><tr><td>Smart contracts across Starknet Sepolia, Ethereum Sepolia, and Madara L3</td><td><strong>20+</strong></td></tr><tr><td>Circom circuits with WASM + zkey</td><td><strong>31</strong></td></tr><tr><td>EZKL (Halo2/KZG) ML models</td><td><strong>2</strong></td></tr><tr><td>On-chain trust receipts</td><td><strong>136+</strong></td></tr><tr><td>Verified proof lanes (Groth16, STARK, Noir HONK, Native KZG)</td><td><strong>5</strong></td></tr></tbody></table><p>Live proof generation and full claim validation: <strong><a href="https://zkde.fi/test" target="_blank" rel="noreferrer">zkde.fi/test</a></strong></p><h2 id="start-here" tabindex="-1">Start Here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start Here&quot;">​</a></h2><p><strong>If you&#39;re a judge or technical reviewer:</strong> Start with <a href="/docs/proof-readout">Live Proof Readout</a> — every claim in these docs is verifiable there. Then read <a href="/docs/proof-pipeline">Proof Pipeline</a>.</p><p><strong>If you&#39;re an integrator:</strong> Start with <a href="/docs/api-overview">API Overview</a> and <a href="/docs/developers">Developers</a>.</p><p><strong>If you&#39;re a user:</strong> Start with <a href="/docs/capital-os">Capital OS</a> and <a href="/docs/trade-desk">Trade Desk</a>.</p><h2 id="core-documentation" tabindex="-1">Core Documentation <a class="header-anchor" href="#core-documentation" aria-label="Permalink to &quot;Core Documentation&quot;">​</a></h2><ul><li><a href="/docs/intro">The Primitive</a> — what the proof system is and why it exists</li><li><a href="/docs/proof-readout">Live Proof Readout</a> — verifiable evidence at <a href="https://zkde.fi/test" target="_blank" rel="noreferrer">zkde.fi/test</a></li><li><a href="/docs/contracts">Deployed Contracts</a> — on-chain contract map across three networks</li><li><a href="/docs/proof-pipeline">Proof Pipeline</a> — ProofMode, verifier lanes, settlement paths</li><li><a href="/docs/privacy-rails">Privacy Rails</a> — commitment → nullifier → claim hash flow</li><li><a href="/docs/zkml-circuits">zkML + Circuit Stack</a> — 13 agent skill circuits, EZKL, ModelBridge</li><li><a href="/docs/api-overview">API Overview</a> — programmatic surface of the proof pipeline</li></ul>`,13)])])}const u=t(i,[["render",n]]);export{f as __pageData,u as default};
